#include <vector>

template <typename T>
class StackBox {
private:
    std::vector<T> items;

public:
    bool isEmpty() const { return items.empty(); }
    void push(T item) { items.push_back(item); }

    T pop() {
        T top = items.back();
        items.pop_back();
        return top;
    }

    T peek() const { return items.back(); }
    int size() const { return (int)items.size(); }
};

