bool balanced(const std::string& text) {
    std::vector<char> stack;
    for (char ch : text) {
        if (ch == '(') stack.push_back(ch);
        else if (ch == ')') {
            if (stack.empty()) return false;
            stack.pop_back();
        }
    }
    return stack.empty();
}
